package com.bank.report;

import java.util.*;
import java.util.logging.*;

public class ReportDemo {
    private static final Logger log = Logger.getLogger("Report");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", 1200000), new Employee("Sneha", 1500000),
            new Employee("Priya", 900000), new Employee("Amit", 700000),
            new Employee("Neha", 650000));
        ComplianceReport report = new ComplianceReport();

        Map<Boolean, Long> counts = report.countByEarnerClass(employees, 1_000_000);
        log.info(() -> "High earners (>1M): " + counts.get(true));
        log.info(() -> "Others: " + counts.get(false));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final double salary;
    Employee(String name, double salary) { this.name = name; this.salary = salary; }
    double getSalary() { return salary; }
}

// ─── Would be in service/ComplianceReport.java ───
class ComplianceReport {
    // partitioningBy ALWAYS yields both true and false keys; counting per side
    Map<Boolean, Long> countByEarnerClass(List<Employee> employees, double threshold) {
        return employees.stream().collect(
            java.util.stream.Collectors.partitioningBy(
                e -> e.getSalary() > threshold,
                java.util.stream.Collectors.counting()));
    }
}
